#include "stdlib/blas/ext/base/ndarray/swhere.h"
#include "stdlib/blas/ext/base/swhere.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"

/**
* Takes elements from one of two one-dimensional single-precision floating-point ndarrays depending on a condition and assigns them to an output ndarray.
*
* @param arrays    list containing a condition, two input ndarrays, and an output ndarray
*/
void stdlib_blas_ext_swhere( const struct ndarray *arrays[] ) {
	const struct ndarray *condition = arrays[ 0 ];
	const struct ndarray *x = arrays[ 1 ];
	const struct ndarray *y = arrays[ 2 ];
	const struct ndarray *out = arrays[ 3 ];

	API_SUFFIX(stdlib_strided_swhere_ndarray)(
		stdlib_ndarray_dimension( condition, 0 ),
		(const bool *)stdlib_ndarray_data( condition ),
		stdlib_ndarray_stride_elements( condition, 0 ),
		stdlib_ndarray_offset_elements( condition ),
		(const float *)stdlib_ndarray_data( x ),
		stdlib_ndarray_stride_elements( x, 0 ),
		stdlib_ndarray_offset_elements( x ),
		(const float *)stdlib_ndarray_data( y ),
		stdlib_ndarray_stride_elements( y, 0 ),
		stdlib_ndarray_offset_elements( y ),
		(float *)stdlib_ndarray_data( out ),
		stdlib_ndarray_stride_elements( out, 0 ),
		stdlib_ndarray_offset_elements( out )
	);
}
